// Check if event already exists based on time and customer email
const events = $input.item.json.events || [];
const bookingTime = $node["Extract Booking Details"].json.appointmentTime;
const customerEmail = $node["Extract Booking Details"].json.email;

const exists = events.some(event => {
  // Check if same time window
  const sameTime = event.start === bookingTime;
  // Check if customer email in attendees or description
  const hasCustomer = event.description?.includes(customerEmail) || 
                     event.attendees?.some(a => a.email === customerEmail);
  return sameTime && hasCustomer;
});

return {
  json: {
    exists: exists,
    eventCount: events.length
  }
};

