// Try different possible field names for the content
const item = $input.first().json;
const text = item.content || item.text || item.body || item.data || item.message || JSON.stringify(item);

if (!text || typeof text !== 'string') {
  throw new Error('Could not find text content. Available fields: ' + Object.keys(item).join(', '));
}

// Extract the JSON block that's already in the message
const jsonMatch = text.match(/\{[^{}]*"name"[^{}]*\}/);
const contactInfo = jsonMatch ? JSON.parse(jsonMatch[0]) : {};

// Extract date/time from natural language
const dayMatch = text.match(/\b(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/i);
const timeMatch = text.match(/(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)/i);
const timezoneMatch = text.match(/(Lagos|Dubai|GMT|UTC|WAT|GST)[\s-]*(?:time)?/i);

// Parse the time
let hour = parseInt(timeMatch?.[1] || '0');
const minutes = timeMatch?.[2] || '00';
const period = timeMatch?.[3]?.toLowerCase().replace(/\./g, '') || 'am';

if (period === 'pm' && hour !== 12) hour += 12;
if (period === 'am' && hour === 12) hour = 0;

// Calculate the actual date for the next occurrence of this day
const days = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const targetDay = days.indexOf(dayMatch?.[1]?.toLowerCase() || '');
const today = new Date();
let daysUntil = targetDay - today.getDay();
if (daysUntil <= 0) daysUntil += 7; // Next week if today or passed

const meetingDate = new Date(today);
meetingDate.setDate(today.getDate() + daysUntil);
const dateStr = meetingDate.toISOString().split('T')[0]; // YYYY-MM-DD

// Client timezone (Lagos = Africa/Lagos = WAT = UTC+1)
// Dubai = Asia/Dubai = GST = UTC+4
const clientTz = timezoneMatch?.[1]?.toLowerCase() === 'dubai' ? 'Asia/Dubai' : 'Africa/Lagos';

return {
  json: {
    name: contactInfo.name || null,
    email: contactInfo.email || null,
    phone: contactInfo.phone || null,
    date: dateStr,
    time_24h: `${hour.toString().padStart(2, '0')}:${minutes}`,
    client_timezone: clientTz,
    // Pre-calculated for Dubai (Mr. Winston's calendar)
    // Lagos is UTC+1, Dubai is UTC+4, so add 3 hours
    dubai_time: `${(hour + 3).toString().padStart(2, '0')}:${minutes}`,
    raw_day: dayMatch?.[1] || null
  }
};

const staffId = $input.first().json['Staff ID'];
const serviceId = $input.first().json['Service ID'];
const email = $input.first().json.customer_email;
const bookingDate = $input.first().json.customer_booking_date;

// Convert date: 2026-02-20 → 20-Feb-2026
const [year, month, day] = bookingDate.split('-');
const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const formattedDate = `${day}-${months[parseInt(month)-1]}-${year}`;

const data = {
  staff_id: staffId,
  service_id: serviceId,
  from_time: formattedDate,
  to_time: formattedDate,
  customer_email: email
};

// Return as simple string - NOT URL encoded
return {
  json: {
    dataString: `data=${JSON.stringify(data)}`,
    formattedDate: formattedDate,
    originalData: data
  }
};

